import { anthropic } from '@ai-sdk/anthropic';
import { uploadFile } from 'ai';
import { run } from '../../lib/run';

run(async () => {
  const files = anthropic.files();
  const uploaded = await uploadFile({
    api: files,
    data: { type: 'text', text: 'Notes for Claude.' },
    filename: 'notes.txt',
  });

  try {
    const metadata = await files.getFileMetadata!({
      file: uploaded.providerReference,
    });
    console.log('Metadata:', metadata);
    // Uploaded files are not downloadable. Use downloadFile for files
    // generated by code execution when metadata.downloadable is true.
    console.log(
      'Downloadable:',
      metadata.providerMetadata?.anthropic?.downloadable,
    );
  } finally {
    const deleted = await files.deleteFile!({
      file: uploaded.providerReference,
    });
    console.log('Deleted:', deleted.deleted);
  }
});
